@backgroundColor: #f6f6f6;
// tweak: { "type": "checkbox", "label": "Show Site Logo", "title": "Show Site Logo", "category": "Checkout", "target": "#store-logo, .checkout-tweak-overlay-logo", "active": false }
// tweak: { "type": "color", "label": "Title Color", "title": "Title Color", "category": "Checkout", "target": "#store-logo h1, .checkout-tweak-overlay-logo", "showOnlyWhenPresent": "body:not(.show-site-logo)" }
@titleColor: #313131;
// tweak: { "type": "color", "label": "Header Color", "title": "Header Color", "category": "Checkout", "target": ".checkout-tweak-background-color", "showOnlyWhenPresent": "body.checkout" }
@headerColor: #fff;
// tweak: { "type": "color", "label": "Header Border Color", "title": "Header Border Color", "category": "Checkout", "target": ".checkout-tweak-background-color", "showOnlyWhenPresent": "body.checkout" }
@headerBorderColor: rgba(0, 0, 0, .06);
// tweak: { "type": "dropdown", "label": "Header Alignment", "title": "Header Alignment", "default": "Left", "options": [ "Left", "Center", "Right" ], "category": "Checkout", "target": ".checkout-tweak-overlay-logo", "showOnlyWhenPresent": "body.checkout" }
// tweak: { "type": "color", "label": "Button Color", "title": "Button Color", "category": "Checkout", "target": "#sqs-standard-checkout .button" }
@buttonColor: #313131;
#sqs-standard-checkout {
  background: @backgroundColor;
}
#store-logo .site-title,
#sqs-standard-checkout .checkout-tweak-site-title-color {
  color: @titleColor;
}
#sqs-standard-checkout .button {
  background: @buttonColor;
}
.checkout-tweak-background-color {
  background: @backgroundColor;
}
.checkout-tweak-header-color {
  background: @headerColor;
}
.checkout-tweak-header-border {
  border-bottom: 1px solid @headerBorderColor;
}
